import re

_SHA256_RE = re.compile(r"[0-9a-f]{64}")
_COMMIT_RE = re.compile(r"(?:[0-9a-f]{40}|[0-9a-f]{64})")


def _require_nonblank(value, name):
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{name} must be a nonblank string")
    return value


def citation_view(fact):
    """Return a validated citation dict with only the canonical fields."""
    if not isinstance(fact, dict):
        raise ValueError("input must be a dict")

    source_id = _require_nonblank(fact.get("source_id"), "source_id")
    path = _require_nonblank(fact.get("path"), "path")

    sha256 = fact.get("sha256")
    if not isinstance(sha256, str) or _SHA256_RE.fullmatch(sha256) is None:
        raise ValueError("sha256 must be 64 lowercase hexadecimal characters")

    commit = fact.get("commit")
    if commit is not None:
        if not isinstance(commit, str) or _COMMIT_RE.fullmatch(commit) is None:
            raise ValueError("commit must be None or a full 40/64 lowercase hexadecimal ID")

    return {
        "source_id": source_id,
        "path": path,
        "sha256": sha256,
        "commit": commit,
    }

