"""RepoMind maintenance helper: resolve query time bounds."""

from datetime import datetime, timezone

from repomind.domain.models import parse_timestamp


def _resolve(value: object, now: datetime) -> datetime:
    """Resolve a query time input to an aware UTC datetime.

    Only None or the empty string default to ``now``. Everything else is
    delegated to ``parse_timestamp`` with date support.
    """
    if value is None or value == "":
        return now
    return parse_timestamp(value, allow_date=True)


def query_clock(as_of, known_at=None, *, now):
    """Return resolved ``as_of`` and ``known_at`` bounds as aware UTC datetimes."""
    resolved_now = parse_timestamp(now)
    if resolved_now.tzinfo is None or resolved_now.utcoffset() is None:
        raise ValueError("now must be timezone-aware")
    resolved_now = resolved_now.astimezone(timezone.utc)
    return {
        "as_of": _resolve(as_of, resolved_now),
        "known_at": _resolve(known_at, resolved_now),
    }

